'use strict';
const {studies,labs,jobs,lenses}=window.portfolioData;
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
function animateContent(element){if(element&&!motionPreference.matches)element.animate([{opacity:.25,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:320,easing:'cubic-bezier(.2,.7,.2,1)'});}

function track(event,label){const payload={event,label,source:'portfolio'};window.dataLayer=window.dataLayer||[];window.dataLayer.push(payload);window.dispatchEvent(new CustomEvent('portfolio:analytics',{detail:payload}));}
const caseGrid=document.getElementById('case-grid');
const caseCard=(s,i)=>`<a class="case-card accent-${s.accent}" style="--card-order:${i}" href="#case/${s.id}" data-event="project_view" data-label="${s.id}"><div class="card-top"><span>${s.company}</span><span class="card-arrow" aria-hidden="true">↗</span></div><div class="case-outcome"><strong>${s.metric}</strong><span>${s.caption}</span></div><div class="case-copy"><h3>${s.title}</h3><p>${s.summary}</p></div><div class="case-foot"><span>${s.proof[0]}</span><span>Read case study <b>↗</b></span></div></a>`;
function renderCases(filter='all'){const selected=filter==='all'?studies:studies.filter(s=>s.group===filter);caseGrid.innerHTML=selected.map(caseCard).join('');document.getElementById('case-count').textContent=`${selected.length} case ${selected.length===1?'study':'studies'}`;}
renderCases();document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderCases(b.dataset.filter);track('case_filter',b.dataset.filter)}));
function lens(id){const item=lenses.find(l=>l.id===id);document.getElementById('lens-content').innerHTML=`<span class="lens-number">0${lenses.indexOf(item)+1}</span><h2>${item.title}</h2><p>${item.body}</p><a href="#case/${item.link}" data-event="project_view" data-label="${item.link}">${item.evidence} <span>↗</span></a>`;document.querySelectorAll('[data-lens]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lens===id)));animateContent(document.getElementById('lens-content'));}
lens('strategy');document.querySelectorAll('[data-lens]').forEach(b=>b.addEventListener('click',()=>lens(b.dataset.lens)));
