document.getElementById('career-panel').innerHTML='<div class="career-timeline">'+jobs.map((j,i)=>{const d=journey[j.id];return `<article class="journey-card" id="journey-${j.id}"><span class="journey-node" aria-hidden="true">0${i+1}</span><div class="journey-top"><span class="eyebrow">${j.theme}</span><span class="journey-date">${j.period}</span></div><h3>${j.company}</h3><p class="journey-role">${j.role}</p><p>${j.intro}</p><ul class="journey-highlights">${d.highlights.map(p=>`<li>${p}</li>`).join('')}</ul><details class="journey-details"><summary><span class="more-label">View more achievements</span><span class="less-label">Show fewer achievements</span><span aria-hidden="true">+</span></summary><div class="journey-expanded"><section><h4>Product & business context</h4><p>${j.intro}</p></section><section><h4>Problems & opportunities</h4><p>${d.problem}</p></section><section><h4>Ownership & leadership contribution</h4><p>${d.ownership}</p></section><section><h4>Product decisions & execution</h4><p>${d.execution}</p></section><section><h4>Business outcomes</h4><div class="journey-facts">${j.facts.map(([v,t])=>`<p><strong>${v}</strong> ${t}</p>`).join('')}</div><ul>${j.points.map(p=>`<li>${p}</li>`).join('')}</ul><p class="journey-recognition">${j.note}</p></section>${j.examples?j.examples.map(e=>`<section><h4>${e.label}</h4><p>${e.body}</p></section>`).join(''):''}<div class="journey-links">${j.links.map(([id,title])=>`<a href="#case/${id}" data-event="project_view" data-label="${id}">${title} ↗</a>`).join('')}</div></div></details></article>`}).join('')+'</div>';
document.querySelectorAll('.journey-details').forEach(d=>d.addEventListener('toggle',()=>{d.closest('.journey-card').classList.toggle('is-expanded',d.open);if(d.open){animateContent(d.querySelector('.journey-expanded'));track('experience_view',d.closest('article').id)}}));
function demoLink(item,cls='text-link'){return item.url?`<a class="${cls}" href="${item.url}" target="_blank" rel="noopener noreferrer" data-event="project_demo_click" data-label="${item.id}" aria-label="${item.cta} (opens in a new tab${item.id==='carenest'?', private owner access required':''})">${item.cta} <span>↗</span></a>`:'';}
function githubLink(item){return item.githubUrl?`<a class="text-link github-link" href="${item.githubUrl}" target="_blank" rel="noopener noreferrer" data-event="project_github_click" data-label="${item.id}" aria-label="${item.title} GitHub (private repository, access required)">GitHub · private ↗</a>`:'';}
