document.getElementById('lab-grid').innerHTML=labs.map(s=>{const c=projectCardContent[s.id];return `<article class="lab-card lab-${s.id}"><div class="product-card-top"><span class="product-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${c.icon}</svg></span><span class="project-status">${s.status}</span></div><div class="lab-body"><span class="product-category">${c.category}</span><h3><a class="project-title-link" href="#lab/${s.id}" data-event="project_view" data-label="${s.id}">${s.title}<span aria-hidden="true">↗</span></a></h3><p class="product-purpose">${c.purpose}</p><p class="product-description">${c.description}</p><ul class="product-features" aria-label="${s.title} capabilities">${c.features.map(f=>`<li>${f}</li>`).join('')}</ul><p class="tech">${s.tech}</p><div class="lab-actions"><a class="product-story-link" href="#lab/${s.id}" data-event="project_view" data-label="${s.id}">Product Story <span>→</span></a>${demoLink(s)}${githubLink(s)}</div><small class="access-note">${s.access||'Local application · no hosted demo'}</small></div></article>`}).join('');
const dialog=document.getElementById('detail-dialog');let previousFocus=null,previousHash='#case-studies',currentItem=null,currentType=null;
const groups={overview:['Business Problem','Product Ownership'],contribution:['Approach','Key Decisions','Cross-functional Collaboration'],outcomes:['Outcomes']};
const caseLabels={'Business Problem':'The Challenge','Product Ownership':'My Role','Approach':'The Approach','Key Decisions':'Product Decisions','Cross-functional Collaboration':'Collaboration','Outcomes':'The Outcome'};
// Unsupported research and trade-off details are omitted, rather than presented as unfinished content.
const supportedCopy=p=>p.replace(/[^.!?]*Details to be added[^.!?]*[.!?]?/g,'').split(/Input needed:/)[0].trim();
const insights={auction:'Standardizing operational workflows can be a product outcome in its own right; this case documents process consistency, without claiming a quantified efficiency gain.',hiring:'This case connects capacity planning to a business outcome: fewer collection delays. The reported result does not establish the model’s methodology or its applicability elsewhere.','bank-partnership':'Banking partnerships add a distribution dimension to lending product work. The documented contribution is support for the initiative, rather than sole ownership of its commercial outcomes.',genai:'AI capability is most relevant here through the customer workflow it improves: campaign creation time, rather than the presence of generation alone.','gold-loan':'A channel launch and a targeted business opportunity are distinct from realized revenue. This case keeps launch delivery separate from commercial ambition.',enterprise:'SaaS ownership spans discovery, roadmap choices, platform integrations, adoption, and delivery predictability. Product scale provides context rather than personal revenue attribution.',salesforce:'Adoption is a useful complement to delivery: the documented outcome connects CRM customization with use across Sales and Operations.'};
function detailView(view){const item=currentItem;const sections=item.sections.filter(([t])=>groups[view].includes(t)).map(([t,p])=>[t,supportedCopy(p)]).filter(([,p])=>p.length>0);document.querySelectorAll('[data-detail-view]').forEach(b=>{const selected=b.dataset.detailView===view;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1});const panel=document.getElementById('case-view-panel');panel.setAttribute('aria-labelledby','detail-tab-'+view);panel.innerHTML=sections.map(([t,p])=>`<section class="detail-section"><h3>${caseLabels[t]||t}</h3><p>${p}</p></section>`).join('');if(view==='outcomes')panel.innerHTML+=`<section class="detail-section product-insight"><h3>Key Product Insight</h3><p>${insights[item.id]}</p><small>Reflection on the documented work.</small></section>`;animateContent(panel);}
function route(){const match=location.hash.match(/^#(case|lab)\/([a-z-]+)$/);if(!match){if(dialog.open)dialog.close();return;}const item=(match[1]==='case'?studies:labs).find(x=>x.id===match[2]);if(!item)return;currentItem=item;currentType=match[1];previousHash=currentType==='case'?'#case-studies':'#product-lab';document.getElementById('detail-type').textContent=currentType==='case'?`CASE STUDY / ${item.company}`:'PRODUCT LAB / INDEPENDENT WORK';
let html=`<span class="eyebrow">${item.context||item.status}</span><h2 id="detail-title" class="detail-heading">${item.title}</h2><p class="detail-intro">${item.intro}</p>${item.businessContext?`<details class="company-context"><summary>Company context <span>+</span></summary><p>${item.businessContext}</p></details>`:''}`;
if(currentType==='case'){html+=`<div class="detail-result accent-${item.accent}"><strong>${item.metric}</strong><span>${item.caption}</span></div><div class="proof-tags">${item.proof.map(p=>`<span>${p}</span>`).join('')}</div><div class="detail-tabs" role="tablist" aria-label="Case study sections"><button role="tab" id="detail-tab-overview" data-detail-view="overview" aria-controls="case-view-panel" aria-selected="true">Problem & ownership</button><button role="tab" id="detail-tab-contribution" data-detail-view="contribution" aria-controls="case-view-panel" aria-selected="false" tabindex="-1">Approach & decisions</button><button role="tab" id="detail-tab-outcomes" data-detail-view="outcomes" aria-controls="case-view-panel" aria-selected="false" tabindex="-1">Outcomes</button></div><div id="case-view-panel" role="tabpanel" tabindex="0" aria-labelledby="detail-tab-overview"></div><div class="case-pagination"><button id="prev-case">← Previous case</button><span>${studies.indexOf(item)+1} / ${studies.length}</span><button id="next-case">Next case →</button></div>`;}else{html+=`<div class="project-open">${demoLink(item,'button primary')}${githubLink(item)}${item.access?`<span>${item.access}</span>`:''}</div>${item.sections.map(([t,p])=>`<details class="project-detail" ${['Problem','Key product decisions'].includes(t)?'open':''}><summary>${t}<span>+</span></summary><p>${p}</p></details>`).join('')}`;}
document.getElementById('detail-content').innerHTML=html;
if(currentType==='case'){detailView('overview');document.querySelectorAll('[data-detail-view]').forEach(b=>b.addEventListener('click',()=>detailView(b.dataset.detailView)));document.querySelector('.detail-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const vs=Object.keys(groups),i=vs.indexOf(document.activeElement.dataset.detailView),n=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:-1)+3)%3;detailView(vs[n]);document.getElementById('detail-tab-'+vs[n]).focus()});document.getElementById('prev-case').onclick=()=>changeCase(-1);document.getElementById('next-case').onclick=()=>changeCase(1);}
if(!dialog.open){previousFocus=document.activeElement;dialog.showModal();document.body.style.overflow='hidden';animateContent(document.getElementById('detail-content'))}dialog.scrollTop=0;document.getElementById('close-dialog').focus();}
function changeCase(direction){const i=studies.indexOf(currentItem);location.hash='case/'+studies[(i+direction+studies.length)%studies.length].id;track('project_view',studies[(i+direction+studies.length)%studies.length].id)}
function closeDetail(){history.replaceState(null,'',previousHash);dialog.close()}
document.getElementById('close-dialog').addEventListener('click',closeDetail);dialog.addEventListener('cancel',e=>{e.preventDefault();closeDetail()});dialog.addEventListener('close',()=>{document.body.style.overflow='';if(previousFocus?.isConnected)previousFocus.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDetail()}});window.addEventListener('hashchange',route);route();
const menu=document.getElementById('menu'),nav=document.getElementById('navigation');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});nav.addEventListener('click',e=>{if(e.target.closest('a')){menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}});
// Provider-neutral hooks; no external tracker or cookies are loaded.
document.addEventListener('click',e=>{const el=e.target.closest('[data-event]');if(el)track(el.dataset.event,el.dataset.label||'')});
const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){nav.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}})},{rootMargin:'-15% 0px -65% 0px'});document.querySelectorAll('main>section[id]').forEach(s=>observer.observe(s));
let ticking=false;function progress(){const distance=document.documentElement.scrollHeight-innerHeight;document.querySelector('.back-top').hidden=scrollY<650||scrollY+innerHeight>=document.documentElement.scrollHeight-90;document.querySelector('.header').classList.toggle('scrolled',scrollY>20);document.querySelector('.reading-progress').style.transform=`scaleX(${distance>0?scrollY/distance:0})`;ticking=false}addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(progress);ticking=true}},{passive:true});progress();

// Practical contact feedback, with a safe fallback when clipboard permissions are unavailable.
const copyEmail=document.querySelector('.copy-email');
copyEmail.addEventListener('click',async()=>{
 const feedback=document.getElementById('contact-feedback');
 try{
  try{await navigator.clipboard.writeText('gaidhane25@gmail.com')}
  catch{
   const field=document.createElement('textarea');field.value='gaidhane25@gmail.com';field.setAttribute('readonly','');field.style.cssText='position:fixed;left:-9999px;top:0';document.body.append(field);field.select();
   const copied=document.execCommand('copy');field.remove();copyEmail.focus();if(!copied)throw new Error('Clipboard unavailable');
  }
  copyEmail.querySelector('.copy-label').textContent='Copied!';copyEmail.classList.add('is-copied');
  feedback.textContent='Email address copied to your clipboard.';track('contact_copy','email');
  setTimeout(()=>{copyEmail.querySelector('.copy-label').textContent='Copy email';copyEmail.classList.remove('is-copied')},2500);
 }catch{feedback.textContent='Copy gaidhane25@gmail.com, or use the email link to open your mail app.';}
});
document.addEventListener('click',event=>{if(nav.classList.contains('open')&&!event.target.closest('.header')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});
// Reveal headings once as they enter the viewport; nothing is hidden before JavaScript runs.
const revealObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){animateContent(entry.target);revealObserver.unobserve(entry.target)}})},{threshold:.12});
document.querySelectorAll('.section-head,.about-grid>div:first-child,.contact-section h2').forEach(el=>revealObserver.observe(el));
